/* SPROWII — скрипт главной, 404 и показа почты в пользовательском соглашении (/skibididop). */
(function () {
  'use strict';
  var $ = function (s) { return document.querySelector(s); };
  var $$ = function (s) { return Array.prototype.slice.call(document.querySelectorAll(s)); };
  var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var canHover = window.matchMedia && window.matchMedia('(hover: hover)').matches;
  var store = { // localStorage бывает недоступен (приватный режим)
    get: function (k) { try { return localStorage.getItem(k); } catch (e) { return null; } },
    set: function (k, v) { try { localStorage.setItem(k, v); } catch (e) {} }
  };

  function init() {
    var root = document.documentElement;

    // год в футере
    var year = $('#year');
    if (year) year.textContent = new Date().getFullYear();

    // ---------- почта: адрес не лежит в HTML, собирается по клику ----------
    $$('[data-e]').forEach(function (el) {
      el.addEventListener('click', function (e) {
        if (el.getAttribute('data-done')) return; // второй клик — обычный mailto
        var addr;
        try { addr = atob(el.getAttribute('data-e')); } catch (err) { return; }
        e.preventDefault();
        el.href = 'mailto:' + addr;
        el.setAttribute('data-done', '1');
        var lbl = el.querySelector('.lbl') || el;
        lbl.textContent = addr;
        if (el.hasAttribute('data-copy')) {
          var btn = document.createElement('button');
          btn.type = 'button'; btn.className = 'copy-btn'; btn.textContent = 'Скопировать';
          btn.addEventListener('click', function () {
            var back = function () { setTimeout(function () { btn.textContent = 'Скопировать'; }, 1800); };
            if (navigator.clipboard && window.isSecureContext) {
              navigator.clipboard.writeText(addr).then(function () { btn.textContent = 'Скопировано ✓'; back(); },
                                                       function () { btn.textContent = 'Выдели и скопируй'; back(); });
            } else { btn.textContent = 'Выдели и скопируй'; back(); }
          });
          el.parentNode.appendChild(btn);
        }
      });
    });

    // ---------- согласие ----------
    var banner = $('#consentBanner');
    function syncBanner() {
      var on = banner && !banner.classList.contains('hidden');
      root.style.setProperty('--bh', on ? banner.offsetHeight + 'px' : '0px');
    }
    if (banner) {
      if (store.get('consent') === '1') banner.classList.add('hidden');
      $('#acceptConsent').addEventListener('click', function () {
        store.set('consent', '1'); banner.classList.add('hidden'); syncBanner();
      });
      $('#declineConsent').addEventListener('click', function () {
        var n = $('#consentNote'); if (n) { n.hidden = false; syncBanner(); }
      });
      syncBanner();
      window.addEventListener('resize', syncBanner);
    }

    // ---------- появление блоков при прокрутке ----------
    var rv = $$('.rv');
    if ('IntersectionObserver' in window && !reduceMotion) {
      var io = new IntersectionObserver(function (list) {
        list.forEach(function (en) { if (en.isIntersecting) { en.target.classList.add('in'); io.unobserve(en.target); } });
      }, { threshold: 0.12, rootMargin: '0px 0px -40px 0px' });
      rv.forEach(function (el) { io.observe(el); });
    } else rv.forEach(function (el) { el.classList.add('in'); });

    // ---------- подсветка карточек за курсором и «магнитные» кнопки ----------
    if (canHover) {
      $$('.project-card').forEach(function (card) {
        card.addEventListener('mousemove', function (e) {
          var r = card.getBoundingClientRect();
          card.style.setProperty('--mx', ((e.clientX - r.left) / r.width * 100) + '%');
          card.style.setProperty('--my', ((e.clientY - r.top) / r.height * 100) + '%');
        });
      });
      if (!reduceMotion) $$('.project-card a, .consent-accept, .pill').forEach(function (btn) {
        btn.addEventListener('mousemove', function (e) {
          var r = btn.getBoundingClientRect();
          btn.style.transform = 'translate(' + ((e.clientX - r.left - r.width / 2) * .2) + 'px,' + ((e.clientY - r.top - r.height / 2) * .2) + 'px) scale(1.05)';
        });
        btn.addEventListener('mouseleave', function () { btn.style.transform = ''; });
      });
    }

    // ---------- прогресс прокрутки, «наверх», активный пункт меню ----------
    var progress = $('.progress-bar'), totop = $('.scroll-top');
    var sections = $$('main section[id]'), navLinks = $$('.nav-links a');
    var ticking = false;
    function onScroll() {
      var y = window.pageYOffset;
      var max = document.documentElement.scrollHeight - window.innerHeight;
      if (progress) progress.style.width = (max > 0 ? Math.min(100, y / max * 100) : 0) + '%';
      if (totop) totop.classList.toggle('visible', y > 400);
      if (navLinks.length) {
        var line = y + window.innerHeight * 0.35, cur = '';
        sections.forEach(function (s) { if (s.offsetTop <= line) cur = s.id; });
        navLinks.forEach(function (a) {
          var on = a.getAttribute('href') === '#' + cur;
          a.classList.toggle('active', on);
          if (on) a.setAttribute('aria-current', 'true'); else a.removeAttribute('aria-current');
        });
      }
      ticking = false;
    }
    if (progress || totop || navLinks.length) {
      window.addEventListener('scroll', function () { if (!ticking) { ticking = true; requestAnimationFrame(onScroll); } }, { passive: true });
      window.addEventListener('resize', onScroll);
      onScroll();
    }
    if (totop) totop.addEventListener('click', function () {
      window.scrollTo({ top: 0, behavior: reduceMotion ? 'auto' : 'smooth' });
    });

    // ---------- модалка перехода на внешний сайт ----------
    var modal = $('#externalModal');
    if (modal) {
      var urlBox = $('#externalUrl'), cont = $('#continueBtn'), cancel = $('#cancelBtn');
      var pending = '', opener = null;
      var open = function (url, from) {
        pending = url; opener = from; urlBox.textContent = url;
        modal.classList.add('active'); modal.setAttribute('aria-hidden', 'false');
        document.body.style.overflow = 'hidden'; cont.focus();
      };
      var close = function () {
        modal.classList.remove('active'); modal.setAttribute('aria-hidden', 'true');
        document.body.style.overflow = ''; pending = '';
        if (opener) opener.focus();
      };
      $$('.external-link').forEach(function (a) {
        a.addEventListener('click', function (e) { e.preventDefault(); open(a.getAttribute('data-url') || a.href, a); });
      });
      cont.addEventListener('click', function () { if (pending) window.open(pending, '_blank', 'noopener,noreferrer'); close(); });
      cancel.addEventListener('click', close);
      modal.addEventListener('click', function (e) { if (e.target === modal) close(); });
      document.addEventListener('keydown', function (e) {
        if (!modal.classList.contains('active')) return;
        if (e.key === 'Escape') close();
        else if (e.key === 'Tab') { e.preventDefault(); (document.activeElement === cont ? cancel : cont).focus(); }
      });
    }

    // ---------- плавающие частицы за заголовком ----------
    var canvas = $('#particles');
    if (canvas && canvas.getContext && !reduceMotion) {
      var ctx = canvas.getContext('2d'), dpr = Math.min(window.devicePixelRatio || 1, 2);
      var w = 0, h = 0, pts = [], mouse = { x: -9999, y: -9999 }, running = false, raf = 0, inView = true;
      var host = canvas.parentElement;

      var resize = function () {
        var r = canvas.getBoundingClientRect(); w = r.width; h = r.height;
        canvas.width = w * dpr; canvas.height = h * dpr; ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        var n = Math.round(Math.min(80, Math.max(26, w * h / 14000))); pts = [];
        for (var i = 0; i < n; i++) pts.push({
          x: Math.random() * w, y: Math.random() * h,
          vx: (Math.random() - .5) * .22, vy: -(0.08 + Math.random() * .3), // медленно всплывают вверх
          r: 0.8 + Math.random() * 1.8, a: 0.35 + Math.random() * .55
        });
      };
      var frame = function () {
        ctx.clearRect(0, 0, w, h);
        var i, j, p, q, dx, dy, d;
        for (i = 0; i < pts.length; i++) {
          p = pts[i]; p.x += p.vx; p.y += p.vy;
          if (p.y < -6) { p.y = h + 6; p.x = Math.random() * w; }
          if (p.x < -6) p.x = w + 6; else if (p.x > w + 6) p.x = -6;
          dx = p.x - mouse.x; dy = p.y - mouse.y; d = dx * dx + dy * dy;
          if (d < 14400 && d > 0) { d = Math.sqrt(d); p.x += dx / d * .9; p.y += dy / d * .9; } // отталкиваются от курсора
          ctx.fillStyle = 'rgba(255,255,255,' + (p.a * .12).toFixed(3) + ')';          // мягкое свечение
          ctx.beginPath(); ctx.arc(p.x, p.y, p.r * 4, 0, 6.2832); ctx.fill();
          ctx.fillStyle = 'rgba(255,255,255,' + p.a.toFixed(3) + ')';
          ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, 6.2832); ctx.fill();
          for (j = i + 1; j < pts.length; j++) {
            q = pts[j]; dx = p.x - q.x; dy = p.y - q.y; d = dx * dx + dy * dy;
            if (d < 10000) {
              ctx.strokeStyle = 'rgba(255,255,255,' + (0.14 * (1 - d / 10000)).toFixed(3) + ')';
              ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(p.x, p.y); ctx.lineTo(q.x, q.y); ctx.stroke();
            }
          }
        }
        raf = requestAnimationFrame(frame);
      };
      var start = function () { if (!running) { running = true; raf = requestAnimationFrame(frame); } };
      var stop = function () { running = false; cancelAnimationFrame(raf); };

      resize(); window.addEventListener('resize', resize);
      host.addEventListener('pointermove', function (e) {
        var r = canvas.getBoundingClientRect(); mouse.x = e.clientX - r.left; mouse.y = e.clientY - r.top;
      });
      host.addEventListener('pointerleave', function () { mouse.x = mouse.y = -9999; });
      if ('IntersectionObserver' in window) {
        new IntersectionObserver(function (en) { inView = en[0].isIntersecting; inView ? start() : stop(); }).observe(canvas);
      } else start();
      document.addEventListener('visibilitychange', function () { (document.hidden || !inView) ? stop() : start(); });
    }
  }

  if (document.readyState !== 'loading') init();
  else document.addEventListener('DOMContentLoaded', init);
})();
